-- PostgreSQL: one atomic statement. Requires an existing users.id = 1.
-- Design: Cobalt name banner, numbered section headings, and a two-column technical skills panel.
-- All profile details, organizations, and accomplishments are fictional.
-- Each execution creates a new resume; IDs are generated by the database.
WITH
content AS (
    SELECT $resume_data$
[
{"label": "Header", "type": "header", "columnPosition": 0, "showHeading": false, "styling": {"backgroundColor": "#2446A0", "color": "#FFFFFF"}, "layout": {"display": "grid", "grid": {"columns": 1}, "padding": {"top": "0rem", "bottom": "0rem"}}, "value": [{"type": "heading", "textAlign": "left", "children": [{"text": "HEADER", "bold": true, "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#2446A0"}]}], "subsections": [{"label": "JANE DOE", "fields": [{"label": "Name", "value": [{"type": "paragraph", "label": "Name", "children": [{"text": "JANE DOE", "fontSizeOffset": 20, "lineHeightOffset": 0, "bold": true, "color": "#FFFFFF"}], "textAlign": "left"}]}, {"label": "Title", "value": [{"type": "paragraph", "label": "Title", "children": [{"text": "SOFTWARE ENGINEER", "fontSizeOffset": 1, "lineHeightOffset": 0, "color": "#FFFFFF"}], "textAlign": "left"}]}, {"label": "Contact", "value": [{"type": "paragraph", "label": "Contact", "children": [{"text": "Denver, CO | (303) 555-0119 | jane.doe@example.com", "fontSizeOffset": -1, "lineHeightOffset": 0, "color": "#FFFFFF"}], "textAlign": "left"}]}]}]},
{"label": "01 / Profile", "type": "summary", "columnPosition": 0, "showHeading": true, "styling": {}, "layout": {"display": "grid", "grid": {"columns": 1}, "padding": {"top": "0rem", "bottom": "0rem"}}, "value": [{"type": "heading", "textAlign": "left", "children": [{"text": "01 / PROFILE", "bold": true, "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#2446A0"}]}], "subsections": [{"label": "Profile", "fields": [{"label": "Summary", "value": [{"type": "paragraph", "label": "Summary", "children": [{"text": "Software engineer with 5 years of experience building dependable web applications and internal tools. Enjoys simplifying complex workflows, improving performance, and collaborating closely with product and design.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}]}]},
{"label": "02 / Experience", "type": "workHistory", "columnPosition": 0, "showHeading": true, "styling": {}, "layout": {"display": "grid", "grid": {"columns": 1}, "padding": {"top": "0rem", "bottom": "0rem"}}, "value": [{"type": "heading", "textAlign": "left", "children": [{"text": "02 / EXPERIENCE", "bold": true, "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#2446A0"}]}], "subsections": [{"label": "Cobalt Systems", "fields": [{"label": "Job Title", "value": [{"type": "paragraph", "label": "Job Title", "children": [{"text": "Software Engineer II", "fontSizeOffset": 1, "lineHeightOffset": 0, "bold": true}]}]}, {"label": "Company", "value": [{"type": "paragraph", "label": "Company", "children": [{"text": "Cobalt Systems | Denver, CO | 2023 - Present", "fontSizeOffset": -0.5, "lineHeightOffset": 0, "color": "#5A6477"}]}]}, {"label": "Description", "value": [{"type": "unordered-list", "children": [{"type": "list-item", "children": [{"text": "Built a customer reporting workspace used by 2,400 monthly active users.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}, {"type": "list-item", "children": [{"text": "Reduced median API response time by 38% through query tuning and targeted caching.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}, {"type": "list-item", "children": [{"text": "Added release checks and monitoring that cut recurring production incidents by 30%.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}]}]}, {"label": "Orbit Grove", "fields": [{"label": "Job Title", "value": [{"type": "paragraph", "label": "Job Title", "children": [{"text": "Software Engineer", "fontSizeOffset": 1, "lineHeightOffset": 0, "bold": true}]}]}, {"label": "Company", "value": [{"type": "paragraph", "label": "Company", "children": [{"text": "Orbit Grove | Remote | 2021 - 2023", "fontSizeOffset": -0.5, "lineHeightOffset": 0, "color": "#5A6477"}]}]}, {"label": "Description", "value": [{"type": "unordered-list", "children": [{"type": "list-item", "children": [{"text": "Delivered accessible React interfaces for account setup and billing workflows.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}, {"type": "list-item", "children": [{"text": "Automated data imports, replacing 8 hours of weekly manual operations work.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}]}]}]},
{"label": "03 / Selected Build", "type": "projects", "columnPosition": 0, "showHeading": true, "styling": {}, "layout": {"display": "grid", "grid": {"columns": 1}, "padding": {"top": "0rem", "bottom": "0rem"}}, "value": [{"type": "heading", "textAlign": "left", "children": [{"text": "03 / SELECTED BUILD", "bold": true, "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#2446A0"}]}], "subsections": [{"label": "Relay", "fields": [{"label": "Project Title", "value": [{"type": "paragraph", "label": "Project Title", "children": [{"text": "Relay - Team Knowledge Search", "fontSizeOffset": 1, "lineHeightOffset": 0, "bold": true}]}]}, {"label": "Description", "value": [{"type": "paragraph", "label": "Description", "children": [{"text": "Built a searchable knowledge hub with document tagging, role-based access, and feedback collection. Piloted with 3 teams and reduced average information lookup time by 45%.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}]}]},
{"label": "04 / Technical Toolkit", "type": "skills", "columnPosition": 0, "showHeading": true, "styling": {"backgroundColor": "#F0F4FC"}, "layout": {"display": "grid", "grid": {"columns": 2}, "padding": {"top": "0rem", "bottom": "0rem"}}, "value": [{"type": "heading", "textAlign": "left", "children": [{"text": "04 / TECHNICAL TOOLKIT", "bold": true, "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#2446A0"}]}], "subsections": [{"label": "Toolkit", "fields": [{"label": "Frontend", "value": [{"type": "paragraph", "label": "Frontend", "children": [{"text": "FRONTEND", "fontSizeOffset": 0, "lineHeightOffset": 0, "bold": true, "color": "#2446A0"}]}]}, {"label": "Backend", "value": [{"type": "paragraph", "label": "Backend", "children": [{"text": "BACKEND", "fontSizeOffset": 0, "lineHeightOffset": 0, "bold": true, "color": "#2446A0"}]}]}, {"label": "Frontend tools", "value": [{"type": "paragraph", "label": "Frontend tools", "children": [{"text": "React / TypeScript / CSS", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}, {"label": "Backend tools", "value": [{"type": "paragraph", "label": "Backend tools", "children": [{"text": "Python / Flask / PostgreSQL", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}, {"label": "Delivery", "value": [{"type": "paragraph", "label": "Delivery", "children": [{"text": "DELIVERY", "fontSizeOffset": 0, "lineHeightOffset": 0, "bold": true, "color": "#2446A0"}]}]}, {"label": "Quality", "value": [{"type": "paragraph", "label": "Quality", "children": [{"text": "QUALITY", "fontSizeOffset": 0, "lineHeightOffset": 0, "bold": true, "color": "#2446A0"}]}]}, {"label": "Delivery tools", "value": [{"type": "paragraph", "label": "Delivery tools", "children": [{"text": "Git / Docker / CI pipelines", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}, {"label": "Quality tools", "value": [{"type": "paragraph", "label": "Quality tools", "children": [{"text": "Testing / Accessibility", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}]}]},
{"label": "05 / Education", "type": "education", "columnPosition": 0, "showHeading": true, "styling": {}, "layout": {"display": "grid", "grid": {"columns": 1}, "padding": {"top": "0rem", "bottom": "0rem"}}, "value": [{"type": "heading", "textAlign": "left", "children": [{"text": "05 / EDUCATION", "bold": true, "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#2446A0"}]}], "subsections": [{"label": "Summit Ridge College", "fields": [{"label": "Degree", "value": [{"type": "paragraph", "label": "Degree", "children": [{"text": "B.S. Computer Science", "fontSizeOffset": 1, "lineHeightOffset": 0, "bold": true}]}]}, {"label": "School", "value": [{"type": "paragraph", "label": "School", "children": [{"text": "Summit Ridge College | 2017 - 2021", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}]}]}
]
$resume_data$::jsonb AS sections
),
new_resume AS (
    INSERT INTO resumes (user_id, title, styling, layout, created_at, updated_at)
    VALUES (
        1,
        'Jane Doe - Blueprint',
        '{"display": "flex", "fontFamily": "Arial, Helvetica, sans-serif", "fontSize": "11.5px", "lineHeight": 1.3, "color": "#28323C", "backgroundColor": "#FFFFFF"}'::json,
        '{"padding": {"top": "2rem", "right": "2rem", "bottom": "2rem", "left": "2rem"}, "gap": {"horizontal": "0.35rem", "vertical": "0.35rem", "subsection": "0.65rem", "field": "0.13rem"}}'::json,
        CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
    )
    RETURNING id, title
),
new_columns AS (
    INSERT INTO columns (resume_id, position, styling, layout, created_at, updated_at)
    SELECT r.id, c.position, '{}'::json, c.layout,
        CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
    FROM new_resume r
    CROSS JOIN (VALUES
        (0, '{"width": {"auto": false, "value": "100%"}, "padding": {"top": "0rem", "bottom": "0rem", "left": "1rem", "right": "1rem"}}'::json)
    ) AS c(position, layout)
    RETURNING id, position
),
section_data AS (
    SELECT (s.ordinality - 1)::integer AS position, s.item
    FROM content
    CROSS JOIN LATERAL jsonb_array_elements(content.sections)
        WITH ORDINALITY AS s(item, ordinality)
),
new_sections AS (
    INSERT INTO sections (
        column_id, label, type, value, show_heading, position,
        styling, layout, created_at, updated_at
    )
    SELECT c.id, s.item->>'label', s.item->>'type',
        (s.item->'value')::json,
        (s.item->>'showHeading')::boolean, s.position,
        (s.item->'styling')::json, (s.item->'layout')::json,
        CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
    FROM section_data s
    JOIN new_columns c ON c.position = (s.item->>'columnPosition')::integer
    RETURNING id, position
),
subsection_data AS (
    SELECT s.id AS section_id, (sub.ordinality - 1)::integer AS position, sub.item
    FROM new_sections s
    JOIN section_data d ON d.position = s.position
    CROSS JOIN LATERAL jsonb_array_elements(d.item->'subsections')
        WITH ORDINALITY AS sub(item, ordinality)
),
new_subsections AS (
    INSERT INTO subsections (
        section_id, label, type, position, styling, layout, created_at, updated_at
    )
    SELECT d.section_id, d.item->>'label', s.item->>'type', d.position,
        '{"fontSizeOffset":0,"lineHeightOffset":0}'::json, '{}'::json,
        CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
    FROM subsection_data d
    JOIN new_sections n ON n.id = d.section_id
    JOIN section_data s ON s.position = n.position
    RETURNING id, section_id, position
),
new_fields AS (
    INSERT INTO fields (
        subsection_id, label, value, position, styling, layout, created_at, updated_at
    )
    SELECT sub.id, f.item->>'label', (f.item->'value')::json,
        (f.ordinality - 1)::integer,
        '{"fontSizeOffset":0,"lineHeightOffset":0}'::json, '{}'::json,
        CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
    FROM new_subsections sub
    JOIN subsection_data d ON d.section_id = sub.section_id AND d.position = sub.position
    CROSS JOIN LATERAL jsonb_array_elements(d.item->'fields')
        WITH ORDINALITY AS f(item, ordinality)
    RETURNING id
)
SELECT id AS resume_id, title, (SELECT count(*) FROM new_fields) AS fields_created
FROM new_resume;
